begin;
insert into auth.users(id,email,raw_user_meta_data,raw_app_meta_data,created_at,updated_at) values('f3180000-0000-4000-8000-000000000001','roster-owner@example.invalid','{}','{}',now(),now());
select set_config('request.jwt.claim.sub','f3180000-0000-4000-8000-000000000001',true);
do $$declare inv jsonb;fresh jsonb;eid uuid;v integer:=1;s jsonb;outcome jsonb;begin
 select jsonb_build_object('sourceUrl','https://example.invalid/reload-roster','selectedModeCode','T19','title','Original invitation','playingTargetPoints','100','playingTargetInnings','20','tableIds',jsonb_build_array('tb01','tb02'),'participants',jsonb_agg(jsonb_build_object('number',i,'name','Spieler '||i))) into inv from generate_series(1,10) i;
 insert into public.calendar_invitation_drafts(source_url,invitation,updated_by) values(inv->>'sourceUrl',inv,auth.uid());
 eid:=public.result_create_internal(inv,auth.uid());
 select inv||jsonb_build_object('selectedModeCode','T16b','title','Reloaded','tableIds',jsonb_build_array('mb01'),'participants',jsonb_agg(jsonb_build_object('number',i,'name','Neu '||(10-i)))) into fresh from generate_series(1,9) i;
 v:=public.refresh_t15_event_data(eid,fresh,v);s:=public.get_t15_result_event(eid);
 if s->'snapshot'->>'selectedModeCode'<>'T16b' or jsonb_array_length(s->'snapshot'->'participants')<>9 or s->'snapshot'->'participants'->0->>'name'<>'Neu 9' or jsonb_array_length(s->'standings'->'C')<>3 then raise exception 'Roster count, order, mode or regrouping failed';end if;
 if s->'snapshot'->'tableIds'<>'["tb01","tb02"]' then raise exception 'Reload changed table configuration';end if;
 if (select invitation from public.calendar_invitation_drafts where source_url=inv->>'sourceUrl')<>inv then raise exception 'Invitation was changed';end if;
 outcome:=public.result_sync_sent_invitation(inv,auth.uid());
 if outcome->>'status'<>'blocked' or (public.get_t15_result_event(eid))->'snapshot'->>'selectedModeCode'<>'T16b' then raise exception 'Automatic invitation update overwrote manual roster';end if;
 begin perform public.refresh_t15_event_data(eid,fresh,v-1);raise exception 'Stale reload accepted';exception when others then if position('VERSION_CONFLICT' in sqlerrm)=0 then raise;end if;end;
 begin perform public.refresh_t15_event_data(eid,jsonb_set(fresh,'{sourceUrl}','"https://example.invalid/other"'),v);raise exception 'Different source accepted';exception when others then if position('Quelle' in sqlerrm)=0 then raise;end if;end;
 update public.user_roles set role='admin' where user_id=auth.uid();
 update public.tournament_operation_tables set event_id=null,assignment=null,last_seen=now();
 perform public.tournament_operation('start',null,eid);
 if (public.get_t15_result_event(eid)->>'can_reload')::boolean then raise exception 'Reload visible in display operation';end if;
 begin perform public.refresh_t15_event_data(eid,fresh,v);raise exception 'Active reload accepted';exception when others then if position('Displaybetrieb' in sqlerrm)=0 then raise;end if;end;
 perform public.tournament_operation('stop',null,eid);
 insert into public.tournament_live_games(event_id,game_key,state,version) values(eid,'A1',public.tournament_initial_score(),1);
 begin perform public.refresh_t15_event_data(eid,fresh,v);raise exception 'Live score reload accepted';exception when others then if position('ersten Ergebniserfassung' in sqlerrm)=0 then raise;end if;end;
 delete from public.tournament_live_games where event_id=eid;
 v:=public.refresh_t15_event_data(eid,inv||'{"selectedModeCode":"T18"}',v);s:=public.get_t15_result_event(eid);
 if jsonb_array_length(s->'snapshot'->'participants')<>10 then raise exception 'Growing roster failed';end if;
 v:=public.save_t15_result(eid,'A1','{"score1":100,"score2":50,"innings1":20,"innings2":20,"high1":20,"high2":10}',v);
 begin perform public.refresh_t15_event_data(eid,fresh,v);raise exception 'Results erased';exception when others then if position('ersten Ergebniserfassung' in sqlerrm)=0 then raise;end if;end;
 perform set_config('request.jwt.claim.sub','f3180000-0000-4000-8000-000000000002',true);
 begin perform public.refresh_t15_event_data(eid,fresh,v);raise exception 'Foreign user allowed';exception when others then if position('Turnierleitung' in sqlerrm)=0 then raise;end if;end;
end $$;
select 'PASS: 10-to-9 roster reload with T16b, seed order, group C, grow back to 10, unchanged invitation/tables, isolation from sent updates, permission/version/source checks, active display/live score/result locks' result;
rollback;
